export function geocodeLocation(locationStr?: string): { lat: number; lng: number } {
  if (!locationStr) return { lat: 40.7128, lng: -74.0060 };
  const lower = locationStr.toLowerCase();
  for (const [key, coords] of Object.entries(CITY_COORDINATES)) {
    if (lower.includes(key)) {
      return coords;
    }
  }
  return { lat: 40.7128, lng: -74.0060 }; // Default to NYC instead of 0,0
}

import { geoNaturalEarth1, geoEquirectangular } from 'd3-geo';

const projNaturalEarth = geoNaturalEarth1().scale(175).translate([500, 260]);
const projEquirectangular = geoEquirectangular().scale(159.155).translate([500, 250]);

export function projectCoords(lat: number, lng: number, mode: 'naturalEarth' | 'equirectangular' = 'naturalEarth'): { x: number; y: number } {
  const proj = mode === 'naturalEarth' ? projNaturalEarth : projEquirectangular;
  const res = proj([lng, lat]);
  if (!res || isNaN(res[0]) || isNaN(res[1])) {
    return { x: 500, y: 260 };
  }
  return { x: Math.round(res[0] * 10) / 10, y: Math.round(res[1] * 10) / 10 };
}

